<script setup lang="ts">
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'

const props = withDefaults(
  defineProps<{
    data: any[]
    loading?: boolean
    emptyText?: string
    currentPage?: number
    pageSize?: number
    pageSizes?: number[]
    total?: number
    layout?: string
    background?: boolean
    showPagination?: boolean
    serverSide?: boolean
  }>(),
  {
    currentPage: 1,
    pageSize: 10,
    pageSizes: () => [10, 20, 50],
    layout: 'total, sizes, prev, pager, next',
    background: true,
    showPagination: true,
    serverSide: false,
  },
)

const { t } = useI18n()

const emit = defineEmits<{
  'update:currentPage': [page: number]
  'update:pageSize': [size: number]
  pageChange: [page: number]
  sizeChange: [size: number]
  rowClick: [row: any]
}>()

const page = computed({
  get: () => props.currentPage,
  set: (val) => emit('update:currentPage', val),
})

const size = computed({
  get: () => props.pageSize,
  set: (val) => {
    emit('update:pageSize', val)
    emit('sizeChange', val)
  },
})

const totalRows = computed(() =>
  props.total !== undefined ? props.total : (props.data || []).length
)

const pagedData = computed(() => {
  if (props.serverSide || !props.showPagination) {
    return props.data || []
  }
  const start = (page.value - 1) * size.value
  return (props.data || []).slice(start, start + size.value)
})

function handlePageChange(val: number) {
  page.value = val
  emit('pageChange', val)
}
</script>

<template>
  <div class="data-table">
    <el-table
      v-loading="loading"
      :data="pagedData"
      :empty-text="emptyText || t('common.noData')"
      stripe
      @row-click="$emit('rowClick', $event)"
    >
      <slot />
    </el-table>
    <el-pagination
      v-if="showPagination && totalRows > 0"
      v-model:current-page="page"
      v-model:page-size="size"
      :page-sizes="pageSizes"
      :total="totalRows"
      :layout="layout"
      :background="background"
      @current-change="handlePageChange"
    />
  </div>
</template>

<style scoped>
.data-table {
  width: 100%;
}

.el-pagination {
  margin-top: 16px;
  display: flex;
  justify-content: flex-end;
}
</style>
